INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7c57cc31-4852-4427-b2d7-02a25e3de1a5', '051b209e-9985-44da-a832-ca884783cb98', 7, 'O Caráter que se Ergue', NULL, '{"intro": "O homem formado \u00e9 aquele que se torna porto seguro para os outros.", "prayer": "Agrade\u00e7a pela jornada de fortalecimento.", "practice": "Fa\u00e7a algo por algu\u00e9m sem esperar nada em troca.", "reflection": "A forma\u00e7\u00e3o termina quando a sua vida se torna um dom.", "journal_prompt": "Quem pode contar com voc\u00ea hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;